function onChunk(chunk, buffer, emit) {
  if (chunk.type === 'content_block_delta' && chunk.delta?.type === 'input_json_delta') {
    buffer.argumentsDelta += chunk.delta.partial_json ?? ''
    emit({ type: 'tool_call_delta', id: buffer.id, argumentsDelta: chunk.delta.partial_json })
  }
}
function finalize(buffer, emit) {
  if (buffer.kind === 'tool') {
    emit({ type: 'tool_call', id: buffer.id, name: buffer.name, arguments: JSON.parse(buffer.argumentsDelta) })
  }
}
// finalize() is called by the provider adapter on its stop signal.

async function pump(res, buffer, emit) {
  for await (const event of sse(res)) {
    switch (event.type) {
      case 'content_block_delta': onChunk(event, buffer, emit); break
      case 'content_block_stop': finalize(buffer, emit); break  // <-- finalizes here
      case 'message_delta': /* usage */ break
      case 'message_stop': emit({ type: 'stop', reason, usage }); break
    }
  }
}
// Anthropic sends the final input_json_delta and content_block_stop in the SAME
// network flush for short tool args; sse() yields them in order, so this is fine
// UNLESS the last delta arrives in a separate read after a partial frame.
